def transform_v3(grid):
    h, w = len(grid), len(grid[0])

    # Find dividers
    row_divs = [i for i in range(h) if grid[i].count(8) == w]
    col_divs = [j for j in range(w) if all(grid[i][j] == 8 for i in range(h))]

    # Get row/col region for an index
    def region_row(idx):
        count = 0
        for d in row_divs:
            if d > idx:
                return count
            count += 1
        return count

    def region_col(idx):
        count = 0
        for d in col_divs:
            if d > idx:
                return count
            count += 1
        return count

    # Initialize output
    output = [[0] * w for _ in range(h)]

    # Mark dividers
    for r in row_divs:
        for c in range(w):
            output[r][c] = 8
    for c in col_divs:
        for r in range(h):
            output[r][c] = 8

    # Collect row values from input
    row_vals = {}
    for r in range(h):
        if r not in row_divs:
            rv = region_row(r)
            vals = set()
            for c in range(w):
                if c not in col_divs and grid[r][c] not in (0, 8):
                    vals.add(grid[r][c])
            if vals:
                row_vals[rv] = max(vals)

    # Collect col values from input
    col_vals = {}
    for c in range(w):
        if c not in col_divs:
            cv = region_col(c)
            vals = set()
            for r in range(h):
                if r not in row_divs and grid[r][c] not in (0, 8):
                    vals.add(grid[r][c])
            if vals:
                col_vals[cv] = max(vals)

    # Fill output - BOTH regions must have content
    for r in range(h):
        for c in range(w):
            if r in row_divs or c in col_divs:
                continue

            rr = region_row(r)
            cc = region_col(c)

            # Get row value for this region
            rv = row_vals.get(rr)
            # Get col value for this region
            cv = col_vals.get(cc)

            # Determine fill value - BOTH regions must have content
            if rv is not None and cv is not None:
                # Both present - check for 6
                if rv == 2 and cv == 3:
                    val = 6
                elif rv == 3 and cv == 2:
                    val = 6
                else:
                    val = rv  # use row value
            else:
                val = 0
            output[r][c] = val

    return output

